 if(id==='gear-form'){if(active().gear.some(g=>g.id!==f.dataset.id&&g.name.trim().toLowerCase()===o.name.trim().toLowerCase()))throw Error('Article déjà présent : modifier sa quantité pour éviter un double comptage');saved=await commit(d=>put(d,'gear',{name:o.name.trim(),category:o.category.trim()||'Autre',grams:n('grams'),qty:n('qty'),kind:o.kind,readyQty:n('readyQty'),ready:n('qty')>0&&n('readyQty')===n('qty')}));}
