 if(id==='log-form')saved=await commit(d=>put(d,'logs',{date:o.date,title:o.title,km:n('km'),up:n('up'),hours:n('hours'),fatigue:n('fatigue'),notes:o.notes,photos:[...photoDraft]}));
 if(id==='safety-form')saved=await commit(d=>Object.assign(d.trips.find(t=>t.id===tid),{contact:o.contact,checkin:o.checkin,emergency:o.emergency}));
