 if(id==='check-form')saved=await commit(d=>d.trips.find(t=>t.id===tid).checklist.push({id:T.uid(),name:o.name.trim(),done:false}));
 if(id==='convert-form')saved=await commit(d=>{const t=d.trips.find(t=>t.id===tid),g=t.gear.find(g=>g.id===f.dataset.id);if(!g||g.kind!=='consumable')throw Error('Consommable absent');t.supplies.push({id:T.uid(),type:o.type,amount:n('amount'),remaining:n('amount'),unit:'g',mode:'transporté',day:1,place:'',source:'Conversion manuelle de '+g.name,checked:'',notes:'Article retiré du matériel pour éviter le double comptage.'});t.gear=t.gear.filter(x=>x.id!==g.id)});
