 if(id==='image-form'){if(!active())throw Error('Choisis une expédition');const file=$('map-image').files[0],old=active().basemap;let data=old?.data;if(file){if(file.size>6e6)throw Error('Image limitée à 6 Mo');data=await new Promise((res,rej)=>{const r=new FileReader;r.onload=()=>res(r.result);r.onerror=()=>rej(r.error);r.readAsDataURL(file)})}if(!data)throw Error('Image requise');saved=await commit(d=>d.trips.find(t=>t.id===tid).basemap={data,north:n('north'),south:n('south'),west:n('west'),east:n('east'),source:o.source,projection:o.projection})}
