function recordingsPanel(t){return t?.recordings.length?`<details class="section-gap"><summary>Traces GPS enregistrées (${t.recordings.length})</summary>${t.recordings.map(r=>`<div class="row"><div><strong>${date(r.startedAt)}</strong><small>${r.points.length} point(s) · ${km(T.metrics([r.points]).km)}</small></div><div>${button('GPX','record-export',r.id)}${button('Retirer','record-delete',r.id,'danger')}</div></div>`).join('')}</details>`:''}
async function parseGearFile(file){const raw=await fileText(file,16e6);let rows;if(file.name.toLowerCase().endsWith('.json')){const x=JSON.parse(raw);if(x.format!=='nexus.gear'||x.version!==1||x.units?.weight!=='g'||!Array.isArray(x.items)||!Array.isArray(x.pack?.entries))throw Error('Export nexus.gear v1 attendu, unité g');const seen=new Set;rows=x.pack.entries.map(e=>{if(seen.has(e.itemId))throw Error('Entrée de matériel dupliquée');seen.add(e.itemId);const matches=x.items.filter(i=>i.id===e.itemId);if(matches.length!==1)throw Error('Référence de matériel absente ou ambiguë');const i=matches[0];return{name:i.name,grams:T.num(i.weight),qty:e.qty,kind:e.kind||i.kind,category:i.category||'Autre'}})}else rows=TrailCSV.parseCSV(raw).map(i=>({name:i.name,grams:i.weight,qty:i.qty,kind:i.kind,category:i.category||'Autre'}));if(rows.length>5000)throw Error('Maximum 5 000 références par import');const t=active(),existing=new Set(t.gear.map(g=>g.name.trim().toLowerCase())),newNames=new Set;for(const r of rows){const key=String(r.name).trim().toLowerCase();if(!key||newNames.has(key)||existing.has(key))throw Error('Article absent ou doublon : '+r.name+' ; corriger avant import pour éviter le double comptage');newNames.add(key)}const result=rows.map(r=>({...r,id:T.uid(),ready:false,readyQty:0}));const test=T.copy(state);test.trips.find(t=>t.id===test.active).gear.push(...result);T.validate(test);return result}
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='trip-select')return setActive(el.value);
 if(el.id==='theme-select')return commit(d=>d.settings.theme=el.value);
 if(el.id==='off-route'){const n=Number(el.value);if(!Number.isInteger(n)||n<25||n>1000)throw Error('Seuil entier entre 25 et 1 000 m');return commit(d=>d.settings.offRoute=n)}
 if(el.id==='region-select'){chosenRegion=el.value;Maps.destroy();render();return}
 if(el.id==='return-select'){returnId=el.value;updateGPS();return}
 if(el.dataset.ready){const id=el.dataset.ready,checked=el.checked;return commit(d=>{const g=d.trips.find(t=>t.id===d.active).gear.find(g=>g.id===id);g.readyQty=checked?g.qty:0;g.ready=checked})}
 if(el.dataset.readyQty){const id=el.dataset.readyQty,n=Number(el.value);return commit(d=>{const g=d.trips.find(t=>t.id===d.active).gear.find(g=>g.id===id);g.readyQty=n;g.ready=n===g.qty&&n>0})}
 if(el.dataset.safety!==undefined){const i=Number(el.dataset.safety),checked=el.checked;return commit(d=>{const t=d.trips.find(t=>t.id===d.active);t.safetyChecks=checked?[...new Set([...t.safetyChecks,i])]:t.safetyChecks.filter(x=>x!==i)})}
 if(el.dataset.check){const id=el.dataset.check,checked=el.checked;return commit(d=>d.trips.find(t=>t.id===d.active).checklist.find(c=>c.id===id).done=checked)}
 if(el.id==='gpx-input'&&el.files[0]){pendingGPX=null;try{pendingGPX=T.parseGPX(await fileText(el.files[0],16e6));const m=T.metrics(pendingGPX.segments);$('gpx-preview').innerHTML=notice(`${m.count} points · ${pendingGPX.segments.length} segment(s) séparés · ${km(m.km)} · ${pendingGPX.waypoints.length} POI à vérifier. ${m.missingElevation?'Altitudes incomplètes.':''}`)+button('Confirmer l’import GPX','gpx-confirm','','primary section-gap')}catch(e){$('gpx-preview').innerHTML=notice('Import refusé : '+esc(e.message))}return}
 if(el.id==='restore-input'&&el.files[0]){pendingRestore=null;try{pendingRestore=T.normalize(JSON.parse(await fileText(el.files[0])));$('restore-preview').innerHTML=notice(`${pendingRestore.trips.length} expédition(s) contrôlée(s). Toutes les expéditions et préférences seront remplacées. Les zones de tuiles sont indépendantes.`)+button('Confirmer le remplacement','restore-confirm','','primary section-gap')}catch(e){$('restore-preview').innerHTML=notice('Restauration refusée : '+esc(e.message))}return}
 if(el.id==='gear-input'&&el.files[0]){pendingGear=null;try{pendingGear=await parseGearFile(el.files[0]);$('gear-preview').innerHTML=notice(pendingGear.length+' références contrôlées, '+pendingGear.filter(g=>g.grams===null).length+' poids inconnu(s).')+`<div class="table-wrap"><table><tr><th>Article</th><th>Quantité</th><th>Poids unitaire</th><th>Type</th></tr>${pendingGear.map(g=>`<tr><td>${esc(g.name)}</td><td>${g.qty}</td><td>${mass(g.grams)}</td><td>${esc(({base:'Base',worn:'Porté',consumable:'Consommable'})[g.kind])}</td></tr>`).join('')}</table></div>`+button('Confirmer l’ajout du matériel','gear-confirm','','primary section-gap')}catch(e){$('gear-preview').innerHTML=notice('Import refusé : '+esc(e.message))}return}
 if(el.id==='region-input'&&el.files[0]){const r=Maps.decodeRegion(JSON.parse(await fileText(el.files[0],120e6)));if(!confirm('Importer la zone « '+r.name+' » contrôlée ? Une zone existante ne sera pas écrasée.'))return;r.id=T.uid();await S.regionWrite(r);Maps.verifyRegion(await S.region(r.id));await loadRegions();chosenRegion=r.id;render();toast('Zone importée et relue sans erreur');return}
 if(el.id==='log-photos'&&el.files.length){const owner=$('log-form'),files=[...el.files];if(photoDraft.length+files.length>4)throw Error('Quatre photos maximum');el.disabled=true;owner.querySelector('button[type="submit"]').disabled=true;try{for(const file of files){if(file.size>15e6)throw Error('Photo supérieure à 15 Mo');const img=await createImageBitmap(file);try{const scale=Math.min(1,1024/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);if($('log-form')!==owner)return;photoDraft.push(canvas.toDataURL('image/jpeg',.78));$('photo-draft').innerHTML=photoHTML()}finally{img.close()}}}finally{if(el.isConnected)el.disabled=false;if(owner.isConnected)owner.querySelector('button[type="submit"]').disabled=false}return}
 }catch(e){toast(e.message)}});
const channel='BroadcastChannel'in window?new BroadcastChannel('trail-command-studio-v2'):null;
channel?.addEventListener('message',async e=>{if(e.data.revision<=state.revision)return;if($('sheet').open||recordId){toast('Un autre onglet a modifié les données ; terminer la saisie puis recharger.');return}try{state=(await S.load()).data;render();toast('Données actualisées depuis un autre onglet')}catch(e){toast(e.message)}});
matchMedia('(prefers-color-scheme: light)').addEventListener('change',theme);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('online',()=>{shell();if(view==='map')updateGPS()});window.addEventListener('offline',()=>{shell();if(view==='map')updateGPS()});window.addEventListener('hashchange',()=>{const k=location.hash.slice(1);if(labels[k])nav(k)});
if('serviceWorker'in navigator&&window.isSecureContext){navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.waiting){waitingSW=reg.waiting;shell()}reg.addEventListener('updatefound',()=>{const sw=reg.installing;sw?.addEventListener('statechange',()=>{if(sw.state==='installed'&&navigator.serviceWorker.controller){waitingSW=reg.waiting;shell();toast('Mise à jour prête ; activation après confirmation')}})})}).catch(e=>toast('Cache PWA non actif : '+e.message));navigator.serviceWorker.addEventListener('controllerchange',()=>{waitingSW=null;shell();toast('Cache PWA actif ; nouveaux fichiers au prochain rechargement. Données conservées.')})}
(async()=>{view=labels[location.hash.slice(1)]?location.hash.slice(1):'home';try{const result=await S.load();state=result.data;loaded=true;await loadRegions();chosenRegion=regions.find(r=>r.valid)?.id||'';render();if(result.migrated)toast('Anciennes données migrées ; clé historique conservée')}catch(e){loaded=true;blocked=e.message;view='data';render()}})();
document.addEventListener('trail-poi-click',e=>poiEditor(e.detail));

function quickLinks(){return `<div class="quick-strip">${['stages','map','prep','weather','pois','safety'].map(k=>`<button data-nav="${k}">${icon(k)}<span>${({stages:'Itinéraire',map:'Cartes',prep:'Préparation',weather:'Météo',pois:'Bivouacs',safety:'Sécurité'})[k]}</span></button>`).join('')}</div>`}
